import{_ as r,C as n,o as e,c as s,j as i,E as d,a as o,a2 as l}from"./chunks/framework.C21TwvGF.js";const z=JSON.parse(`{"title":"2-hafta (Mentor)","description":"","frontmatter":{"title":"2-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (DevOps)","link":"/mentor/10-sinf-devops/"},"n":2,"bob":"I-bob · Operatsion tizimlar (Linux)","lessons":[{"g":4,"title":"Xizmatlar va jarayonlarni boshqarish (ps, top, kill, systemd)","lead":"Linux operatsion tizimi tomir urishi: jarayonlar monitoringi (ps, top), boshqaruv signallari (kill, nice) hamda doimiy ishlovchi xizmatlar (systemd/systemctl).","link":"/mentor/10-sinf-devops/hafta-02/dars-1","slide":"/slaydlar/10-sinf-devops/hafta-02/dars-1.html","test":"/slaydlar/10-sinf-devops/hafta-02/dars-1-test.html"},{"g":5,"title":"Disklar, fayl tizimlari va paket menejerlari (APT, DNF)","lead":"Linuxda xotira boshqaruvi: disklar va bo'limlar arxitekturasi (df, du, mount), zamonaviy fayl tizimlari hamda xavfsiz dastur o'rnatish tizimi (APT/DNF).","link":"/mentor/10-sinf-devops/hafta-02/dars-2","slide":"/slaydlar/10-sinf-devops/hafta-02/dars-2.html","test":"/slaydlar/10-sinf-devops/hafta-02/dars-2-test.html"},{"g":6,"title":"Git va versiya boshqaruvi tizimlariga kirish (Git asoslari)","lead":"Dasturiy ta'minotning vaqt mashinasi: Git versiya boshqaruvi, 3 ta hudud (Working, Staging, Repository), commitlar anatomiyasi va .gitignore sirlari.","link":"/mentor/10-sinf-devops/hafta-02/dars-3","slide":"/slaydlar/10-sinf-devops/hafta-02/dars-3.html","test":"/slaydlar/10-sinf-devops/hafta-02/dars-3-test.html"}],"test":"/slaydlar/10-sinf-devops/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-devops/hafta-02/index.md","filePath":"mentor/10-sinf-devops/hafta-02/index.md"}`),h={name:"mentor/10-sinf-devops/hafta-02/index.md"},m={class:"blk"},g={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},c={class:"blk"},u={id:"baholash-mezoni",tabindex:"-1"};function y(v,a,b,f,k,q){const t=n("Icon");return e(),s("div",null,[i("div",m,[i("h2",g,[d(t,{name:"house"}),a[0]||(a[0]=o(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=l('<p>2-haftada jarayonlar (processes) va systemd xizmatlarini boshqarish, disklar va fayl tizimlari tahlili (df/du), paket menejerlari (APT) hamda Git versiya boshqaruvi tizimining poydevori (init, add, commit, .gitignore) o&#39;rganildi. Quyidagi vazifalar amaliy ko&#39;nikmalarni mustahkamlash uchun berilgan.</p><hr><h2 id="_4-dars-vazifasi-jarayonlar-va-xizmatlar" tabindex="-1">4-dars vazifasi: Jarayonlar va Xizmatlar <a class="header-anchor" href="#_4-dars-vazifasi-jarayonlar-va-xizmatlar" aria-label="Permalink to &quot;4-dars vazifasi: Jarayonlar va Xizmatlar&quot;">​</a></h2><ol><li>Terminalda <code>top</code> yoki <code>htop</code> dasturini oching. Tizimingizda umumiy nechta jarayon mavjudligi, ulardan nechtasi faol («running») holatda ekanini daftaringizga qayd eting.</li><li><code>sleep 400 &amp;</code> buyrug&#39;i yordamida yangi fon jarayonini ishga tushiring. <code>jobs</code> va <code>ps aux | grep sleep</code> buyruqlari yordamida uning PID raqamini aniqlang.</li><li>Aniqlangan PID raqami bo&#39;yicha <code>kill [PID]</code> buyrug&#39;i bilan ushbu jarayonni to&#39;xtating.</li><li><code>systemctl status cron</code> (yoki <code>crond</code>) buyrug&#39;ini bajarib, rejalashtiruvchi xizmatning faol holatini tekshiring. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h2 id="_5-dars-vazifasi-disk-sarfi-va-paketlar" tabindex="-1">5-dars vazifasi: Disk sarfi va Paketlar <a class="header-anchor" href="#_5-dars-vazifasi-disk-sarfi-va-paketlar" aria-label="Permalink to &quot;5-dars vazifasi: Disk sarfi va Paketlar&quot;">​</a></h2><ol><li><code>df -h</code> buyrug&#39;ini bajaring va asosiy ildiz (<code>/</code>) bo&#39;limida qancha umumiy hajm, ishlatilgan hajm va bo&#39;sh joy qolganini aniqlang.</li><li>O&#39;z uy katalogingizdagi barcha papkalar hajmini <code>du -sh ~/* | sort -h</code> orqali saralangan holda ko&#39;ring va eng katta 3 ta papkani yozib oling.</li><li><code>sudo apt update</code> buyrug&#39;i orqali paketlar indeksini yangilang, so&#39;ngra <code>sudo apt install -y curl wget ncdu</code> buyruqlari bilan ushbu utilitalarni o&#39;rnating.</li><li><code>ncdu ~</code> dasturini ishga tushirib, interaktiv terminal orqali xotira taqsimotini tahlil qiling. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h2 id="_6-dars-vazifasi-git-va-repozitoriya-asoslari" tabindex="-1">6-dars vazifasi: Git va Repozitoriya asoslari <a class="header-anchor" href="#_6-dars-vazifasi-git-va-repozitoriya-asoslari" aria-label="Permalink to &quot;6-dars vazifasi: Git va Repozitoriya asoslari&quot;">​</a></h2><ol><li>Uy katalogingizda <code>my_git_lab</code> nomli yangi papka oching va uni <code>git init</code> orqali Git omboriga aylantiring.</li><li>Repozitoriya ichida <code>app.py</code>, <code>README.md</code> va <code>database.log</code> fayllarini yarating.</li><li><code>.gitignore</code> faylini yaratib, uning ichiga <code>*.log</code> qoidasini yozing.</li><li><code>git status</code> orqali <code>database.log</code> ning e&#39;tiborsiz qoldirilganini tekshiring.</li><li>Qolgan fayllarni <code>git add .</code> qiling va <code>git commit -m &quot;feat: dastlabki fayllar yaratildi&quot;</code> izohi bilan birinchi commitni amalga oshiring.</li><li><code>README.md</code> fayliga bitta yangi qator qo&#39;shib, uni ikkinchi commit bilan tarixga saqlang (<code>git commit -m &quot;docs: README yangilandi&quot;</code>).</li><li><code>git log --oneline</code> natijasini daftaringizga ko&#39;chirib yozing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><ul><li><strong>Tekshirish mezonlari:</strong><ol><li>O&#39;quvchi jarayonlarni fonga o&#39;tkazish (<code>&amp;</code>, <code>Ctrl+Z</code>, <code>bg</code>, <code>fg</code>) va to&#39;xtatish (<code>kill</code>, <code>killall</code>) mexanizmini to&#39;liq o&#39;zlashtirganmi.</li><li><code>df</code> va <code>du</code> buyruqlarining amaliy farqi tushunilganmi (umumiy bo&#39;lim vs aniq katalog).</li><li><code>apt update</code> va <code>apt install</code> mantiqan to&#39;g&#39;ri ketma-ketlikda bajarilganmi.</li><li>Git&#39;ning 3 ta hududi (Working, Staging, Repo) to&#39;g&#39;ri qo&#39;llanganmi, commit izohlari standart qolipda yozilganmi.</li><li><code>.gitignore</code> fayli orqali loglar to&#39;g&#39;ri filtrlanganmi.</li></ol></li><li><strong>Tez-tez uchraydigan xatolar:</strong><ul><li><code>kill</code> buyrug&#39;iga job raqami (<code>%1</code>) o&#39;rniga oddiy raqam berish yoki PID raqami bilan adashtirish.</li><li><code>git commit</code> qilishdan oldin <code>git add</code> qilishni unutish (Changes not staged for commit).</li><li><code>.gitignore</code> ga fayl qo&#39;shishdan oldin uni allaqachon commit qilib qo&#39;yish (kuzatuvga kirib qolgan faylni keshdan tozalash kerak bo&#39;ladi).</li></ul></li></ul>',13))]),i("div",c,[i("h2",u,[d(t,{name:"list-checks"}),a[3]||(a[3]=o(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=l('<p><strong>Mavzular:</strong></p><ol><li>Xizmatlar va jarayonlarni boshqarish (ps, top, htop, nice, kill signallari, systemd va systemctl)</li><li>Disk, fayl tizimlari (df, du, fdisk, mount) va paket menejerlari (APT, DNF, paketlarni o&#39;rnatish va yangilash)</li><li>Git va versiya boshqaruvi tizimlariga kirish: VCS konsepsiyasi, git init, status, add, commit, log va .gitignore</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Jarayonlar va Xizmatlar</strong></td><td>PID, Foreground/Background boshqaruvi, signallar (SIGTERM/SIGKILL), systemctl amallari</td><td>30 ball</td></tr><tr><td><strong>Disklar va Paketlar</strong></td><td>df -h, du -sh saralash, blokli qurilmalar, mount nuqtasi, apt update/install/purge</td><td>30 ball</td></tr><tr><td><strong>Git Asoslari va Amaliyot</strong></td><td>3 ta hudud (Working, Staging, Repo), git init, add, commit, log va .gitignore sozlash</td><td>40 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Jarayonlar (30)</th><th>Disk &amp; Paket (30)</th><th>Git Asoslari (40)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar Git&#39;da faylni o&#39;zgartirgandan keyin to&#39;g&#39;ridan-to&#39;g&#39;ri <code>git commit</code> qilishga urinishlari va «no changes added to commit» xatoligiga uchrashlari mumkin. <code>git add</code> ning zarurati (Staging Area bosqichi) yana bir bor amalda ko&#39;rsatilishi lozim.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> <code>systemd</code> xizmati sifatida oddiy Python veb-skriptini avtomat ishga tushuvchi daemon qilish yoki <code>ncdu</code> bilan butun tizim bo&#39;yicha eng katta fayllarni xaritada tahlil qilish topshirig&#39;i berilishi mumkin.</li></ul>',11))])])}const _=r(h,[["render",y]]);export{z as __pageData,_ as default};
